package com.aditya.day13.delivery; import jakarta.persistence.*; import java.util.*; @Entity public class DeliveryPartner{@Id @GeneratedValue(strategy=GenerationType.UUID)UUID id;String name;boolean online,available;double lat,lng;public UUID getId(){return id;}public String getName(){return name;}public void setName(String x){name=x;}public boolean isOnline(){return online;}public void setOnline(boolean x){online=x;}public boolean isAvailable(){return available;}public void setAvailable(boolean x){available=x;}public double getLat(){return lat;}public void setLat(double x){lat=x;}public double getLng(){return lng;}public void setLng(double x){lng=x;}}